BR_UI_07_SCRIPT = r"""
<script>
(function(){
  var STORAGE_KEY='br_ui_sessions_v2';
  var LEGACY_KEY='br_ui_sessions_v1';
  var activeSession=null;
  function byId(id){return document.getElementById(id)}
  function token(){return localStorage.getItem('mission_control_token')||''}
  function aiProvider(){var p=localStorage.getItem('mission_control_ai_provider')||'openai';if(p!=='openai'&&p!=='deepseek'){p='openai';localStorage.setItem('mission_control_ai_provider',p)}return p}
  function aiModel(){var p=aiProvider();var m=localStorage.getItem('mission_control_ai_model')||'';var openai=['gpt-5.5','gpt-5.5-mini','gpt-5.5-thinking'];var deepseek=['deepseek-v4-pro','deepseek-v4-flash'];var models=p==='deepseek'?deepseek:openai;var fallback=p==='deepseek'?'deepseek-v4-pro':'gpt-5.5';if(models.indexOf(m)<0){m=fallback;localStorage.setItem('mission_control_ai_model',m)}return m}
  function aiPayload(){return {provider:aiProvider(),model:aiModel()}}
  function post(url,body){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){return r.json()})}
  function safe(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function providerLabel(){return aiProvider()==='deepseek'?'DeepSeek':'OpenAI'}
  function aiEngineText(){return providerLabel()+' · '+aiModel()}
  function copyText(text,button){function show(label,ok){if(button){button.textContent=label;button.classList.toggle('copied',!!ok);setTimeout(function(){button.textContent='Copy';button.classList.remove('copied')},1400)}}function success(){show('Copied ✓',true)}function failed(){show('Copy failed',false)} if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text||'').then(success).catch(function(){fallbackCopy(text,success,failed)})}else{fallbackCopy(text,success,failed)}}
  function fallbackCopy(text,success,failed){var ta=document.createElement('textarea');ta.value=text||'';ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();var ok=false;try{ok=document.execCommand('copy')}catch(e){ok=false}document.body.removeChild(ta);if(ok){success()}else{failed()}}
  window.refreshBoardAiEngine=function(){var text='AI engine: '+aiEngineText();var chip=byId('activeAiEngineChip');if(chip)chip.textContent=text;var value=byId('activeAiEngineValue');if(value)value.textContent=aiEngineText();var desc=byId('activeAiEngineDescription');if(desc)desc.textContent='Board Room, Scope, and Runtime calls use this selection.'}
  function labelFor(key){return String(key||'').split('_').map(function(x){return x.charAt(0).toUpperCase()+x.slice(1)}).join(' ')}
  function now(){return new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
  function sessions(){try{var v=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(v)return v;return JSON.parse(localStorage.getItem(LEGACY_KEY)||'[]')}catch(e){return []}}
  function saveSessions(items){localStorage.setItem(STORAGE_KEY,JSON.stringify(items.slice(0,30)))}
  function groupName(iso){var d=new Date(iso||Date.now()), today=new Date();var start=new Date(today.getFullYear(),today.getMonth(),today.getDate());var delta=(start-new Date(d.getFullYear(),d.getMonth(),d.getDate()))/86400000;if(delta<=0)return'Today';if(delta===1)return'Yesterday';if(delta<7)return'Previous 7 Days';return'Older'}
  function ensureBoardWorkspace(){
    var board=byId('board'); if(!board || board.dataset.brUi07==='ready') return;
    board.dataset.brUi07='ready';
    board.innerHTML="<div class='br-shell'><section class='card br-thread-card'><div class='br-header'><div><div class='brand-small'>Board Room</div><h2>Executive Workspace</h2><p class='muted'>A CEO-grade conversation for strategy, architecture, governance, and execution.</p><div class='br-status'><span class='br-chip live'>Runtime Constitution loaded</span><span class='br-chip'>Founder approval enforced</span><span id='activeAiEngineChip' class='br-chip'>AI engine: '+safe(aiEngineText())+'</span><span class='br-chip'>⌘K history</span></div></div><div class='br-header-actions'><button class='secondary' onclick='toggleHistory()'>History</button><button class='secondary' onclick='newBoardChat()'>New Chat</button></div></div><div id='brHistory' class='br-history'><div class='small'>Board Room sessions</div><div class='br-history-top'><input id='brHistorySearch' placeholder='Search conversations...' oninput='renderHistory()'><button class='secondary' onclick='renameActiveSession()'>Rename</button><button class='secondary' onclick='deleteActiveSession()'>Delete</button></div><div id='brHistoryRow' class='br-history-row'></div></div><div id='brThread' class='br-thread'></div><div class='br-composer'><textarea id='message' placeholder='Message the Board Room...'></textarea><button id='boardBtn' class='primary' onclick='boardRoomChat()'>Send</button></div></section><aside class='card br-advisor'><div class='brand-small'>Executive Brief</div><h2>Live Signal</h2><div class='br-brief'><div class='br-mini'><strong>AI Engine</strong><div id='activeAiEngineValue' class='value'>"+safe(aiEngineText())+"</div><p id='activeAiEngineDescription' class='muted'>Board Room, Scope, and Runtime calls use this selection.</p></div><div class='br-mini'><strong>Intent</strong><div id='conversationMode' class='value'>General Conversation</div><p id='modeDescription' class='muted'>No message yet.</p></div><div id='executiveDecisionCard' class='br-mini'><strong>Recommended Action</strong><div class='value'>None yet</div><p class='muted'>Send a message first.</p></div><div class='br-mini'><strong>Decisions</strong><ul id='decisionMinutes' class='br-list'><li>No decisions captured yet.</li></ul></div><div class='br-mini'><strong>Actions</strong><ul id='actionMinutes' class='br-list'><li>No actions captured yet.</li></ul></div><div class='br-mini'><strong>Knowledge</strong><ul id='knowledgeMinutes' class='br-list'><li>Important context will appear here.</li></ul></div><div id='workflowCard' class='br-mini'><strong>Current Mission</strong><div class='value'>None</div><p class='muted'>Workflow appears only after you accept an inline recommendation.</p></div><p id='meetingMeta' class='muted'>No meeting yet.</p></div></aside></div>";
    renderWelcome(); renderHistory(); refreshBoardAiEngine();
    var input=byId('message'); if(input){input.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();window.boardRoomChat()}})}
  }
  function thread(){ensureBoardWorkspace();return byId('brThread')}
  function markdown(text){var s=safe(text||'');s=s.replace(/```([\s\S]*?)```/g,function(_,c){return '<pre><code>'+c+'</code></pre>'});s=s.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>');s=s.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');s=s.replace(/(?:^|\n)- (.*)(?=\n|$)/g,'\n<li>$1</li>').replace(/(<li>[\s\S]*?<\/li>)/g,'<ul>$1</ul>');return s.replace(/\n/g,'<br>')}
  function renderWelcome(){var box=byId('brThread'); if(!box) return; box.innerHTML="<div class='br-welcome'><h3>Welcome back, Toni.</h3><p class='muted'>I can help review architecture, prioritize missions, prepare governance-safe proposals, audit the repository, or guide product strategy. What would you like to accomplish today?</p><div class='br-starters'><button onclick='useStarter(\'Review Mission Control architecture and recommend the next engineering mission.\')'>Review architecture</button><button onclick='useStarter(\'Identify technical debt and recommend a safe implementation plan.\')'>Find technical debt</button><button onclick='useStarter(\'Create an engineering proposal for the next highest-impact mission.\')'>Create proposal</button></div></div>"; activeSession={id:'S'+Date.now(),title:'New Board Room chat',messages:[],updated_at:new Date().toISOString(),created_at:new Date().toISOString(),pinned:false}}
  function addMsg(role,text,decision,workflow,skipPersist,opts){opts=opts||{}; var box=thread(); if(!box) return; var div=document.createElement('div'); div.className='br-msg '+(role==='user'?'user':'board'); var avatar=document.createElement('div'); avatar.className='br-avatar'; avatar.textContent=role==='user'?'TT':'AI'; var wrap=document.createElement('div'); wrap.className='br-content'; var name=document.createElement('div'); name.className='br-name'; name.innerHTML=(role==='user'?'You':'Board Room')+' <span class="br-time">'+now()+'</span>'; var bubble=document.createElement('div'); bubble.className='br-bubble br-md'; if(opts.error)bubble.classList.add('br-error'); if(opts.streaming)bubble.classList.add('streaming'); if(opts.markdown){bubble.innerHTML=markdown(text||'')}else{bubble.textContent=text||''} wrap.appendChild(name); wrap.appendChild(bubble); var copy=document.createElement('button'); copy.className='br-copy'; copy.textContent='Copy'; copy.dataset.copyText=text||''; copy.onclick=function(){copyText(copy.dataset.copyText||'',copy)}; wrap.appendChild(copy); if(decision&&(decision.primary_action||(decision.action_buttons&&decision.action_buttons.length))){wrap.appendChild(actionCard(decision))} if(workflow){wrap.appendChild(workflowInlineCard(workflow))} if(role==='user'){div.appendChild(wrap);div.appendChild(avatar)}else{div.appendChild(avatar);div.appendChild(wrap)} box.appendChild(div); box.scrollTop=box.scrollHeight; if(activeSession&&!skipPersist){activeSession.messages.push({role:role,text:text,at:new Date().toISOString()}); if(role==='user'&&activeSession.messages.filter(function(m){return m.role==='user'}).length===1)activeSession.title=autoTitle(text); persistActiveSession()} return div}
  function streamMsg(text,decision,workflow){var full=String(text||''), shown='', i=0; var msg=addMsg('board','',null,null,true,{streaming:true,markdown:true}); var bubble=msg&&msg.querySelector('.br-bubble'); var content=msg&&msg.querySelector('.br-content'); var copy=msg&&msg.querySelector('.br-copy'); return new Promise(function(resolve){var timer=setInterval(function(){shown+=full.slice(i,i+3);i+=3;if(bubble)bubble.innerHTML=markdown(shown);if(copy)copy.dataset.copyText=shown;var box=thread();box.scrollTop=box.scrollHeight;if(i>=full.length){clearInterval(timer);if(copy)copy.dataset.copyText=full;if(bubble)bubble.classList.remove('streaming');if(content&&decision&&(decision.primary_action||(decision.action_buttons&&decision.action_buttons.length)))content.appendChild(actionCard(decision));if(content&&workflow)content.appendChild(workflowInlineCard(workflow)); if(activeSession){activeSession.messages.push({role:'board',text:full,at:new Date().toISOString()});persistActiveSession()}resolve(msg)}},12)})}
  function autoTitle(text){var t=String(text||'').replace(/\s+/g,' ').trim();return t?t.slice(0,64):'Untitled Board Room chat'}
  function persistActiveSession(){if(!activeSession)return;activeSession.updated_at=new Date().toISOString();var items=sessions().filter(function(s){return s.id!==activeSession.id});items.unshift(activeSession);saveSessions(items.sort(function(a,b){return (b.pinned?1:0)-(a.pinned?1:0)||new Date(b.updated_at)-new Date(a.updated_at)}));renderHistory()}
  window.renderHistory=function(){var row=byId('brHistoryRow'); if(!row)return; var q=(byId('brHistorySearch')&&byId('brHistorySearch').value||'').toLowerCase(); var items=sessions().filter(function(s){return !q||(s.title||'').toLowerCase().indexOf(q)>=0||(s.messages||[]).some(function(m){return String(m.text||'').toLowerCase().indexOf(q)>=0})}); if(!items.length){row.innerHTML='<span class="muted">No matching sessions.</span>'; return} row.innerHTML=''; var last=''; items.forEach(function(s){var g=s.pinned?'Pinned':groupName(s.updated_at); if(g!==last){var h=document.createElement('div');h.className='br-history-group';h.textContent=g;row.appendChild(h);last=g} var card=document.createElement('div');card.className='br-session '+(activeSession&&s.id===activeSession.id?'active':'');card.innerHTML='<div class="br-session-title">'+safe(s.title||'Untitled')+'</div><small>'+safe((s.messages||[]).length+' messages · '+new Date(s.updated_at).toLocaleString())+'</small><div class="br-session-actions"><button onclick="loadSession(\''+s.id+'\')">Open</button><button onclick="pinSession(\''+s.id+'\')">'+(s.pinned?'Unpin':'Pin')+'</button><button onclick="renameSession(\''+s.id+'\')">Rename</button><button onclick="deleteSession(\''+s.id+'\')">Delete</button></div>';row.appendChild(card)})}
  function actionCard(decision){
    var buttons=(decision&&decision.action_buttons)||[];
    if(!buttons.length&&decision&&decision.primary_action){
      var a=decision.primary_action;
      buttons=[{label:a.label||labelFor(a.key),action_type:a.requires_workflow?'function':'note',target:a.requires_workflow?'createWorkflow':'addInlineNote',payload:{text:a.requires_workflow?'':'Continue discussion selected.'}}].concat((decision.alternative_actions||[]).slice(0,2).map(function(x){return {label:x.label||labelFor(x.key),action_type:x.requires_workflow?'function':'note',target:x.requires_workflow?'createWorkflow':'addInlineNote',payload:{text:'Alternative noted: '+(x.label||labelFor(x.key))}}}));
      buttons.push({label:'Save Session',action_type:'function',target:'saveCurrentSession',payload:{}})
    }
    if(!buttons.length)return document.createTextNode('');
    var card=document.createElement('div');
    card.className='br-actions-card';
    var title=decision.recommended_action||(decision.primary_action&&decision.primary_action.label)||'Recommended next action';
    var copyTextValue=decision.handoff_prompt||('Recommendation: '+title+'\nReason: '+(decision.reason||'Board Room selected the safest next action.'));
    card.innerHTML='<div class="small">'+safe(decision.intent_type||'Contextual action')+'</div><h3>'+safe(title)+'</h3><p class="muted">'+safe(decision.reason||'Actions are tied to the recommended next step.')+'</p>';
    var row=document.createElement('div');
    row.className='br-actions';
    buttons.forEach(function(button){var el=document.createElement('button');el.className=button.action_type==='post'?'primary':'secondary';el.textContent=button.label||'Action';el.onclick=function(){runActionButton(button,el)};row.appendChild(el)});
    card.appendChild(row);
    if(decision.technical_details){
      var details=document.createElement('details');
      var summary=document.createElement('summary');
      summary.textContent='Technical Details';
      var technical=document.createElement('pre');
      technical.textContent=JSON.stringify(decision.technical_details,null,2);
      details.appendChild(summary);
      details.appendChild(technical);
      card.appendChild(details)
    }
    var copy=document.createElement('button');
    copy.className='br-copy';
    copy.textContent='Copy';
    copy.dataset.copyText=copyTextValue;
    copy.onclick=function(){copyText(copy.dataset.copyText||'',copy)};
    card.appendChild(copy);
    return card
  }
  async function runActionButton(button,el){var payload=button.payload||{};if(button.action_type==='copy'){copyText(typeof payload==='string'?payload:JSON.stringify(payload,null,2),el);return}if(button.action_type==='show_section'){if(window.showSection)window.showSection(button.target);else if(button.target==='executions'&&document.querySelector('[data-section="executions"]'))document.querySelector('[data-section="executions"]').click();return}if(button.action_type==='function'&&window[button.target]){window[button.target]();return}if(button.action_type==='note'){addInlineNote(payload.text||button.label||'Action noted.');return}if(button.action_type==='post'){var body=Object.assign({token:token()},payload);el.disabled=true;try{var data=await post(button.target,body);addMsg('board',founderResponse(data,'The requested action is ready for review.'),null,null,false,{markdown:true})}catch(e){addMsg('board','Action failed: '+e,null,null,false,{error:true})}finally{el.disabled=false}}}
  function workflowInlineCard(wf){var card=document.createElement('div'); card.className='br-workflow-card'; var copyTextValue='Workflow: '+(wf.title||'Workflow')+'\nStatus: '+(wf.status||'')+'\nID: '+(wf.workflow_id||''); var html='<div class="small">Founder workflow</div><h3>'+safe(wf.title||'Workflow')+'</h3><p class="muted">'+safe(wf.status)+' · '+safe(wf.workflow_id)+'</p>'; if(wf.stages){wf.stages.forEach(function(s){var mark=s.state==='complete'?'✓':(s.state==='current'?'●':'○');copyTextValue+='\n'+mark+' '+(s.label||'')+' - '+(s.state||'');html+='<div class="br-stage '+safe(s.state)+'">'+mark+' '+safe(s.label)+'</div>'})} if(wf.allowed_actions&&wf.allowed_actions.length){copyTextValue+='\nAllowed actions: '+wf.allowed_actions.join(', ');html+='<div class="br-actions">';wf.allowed_actions.forEach(function(a){html+='<button class="'+(a.indexOf('approve')>=0?'primary':'secondary')+'" onclick="workflowAction(\''+a+'\')">'+labelFor(a)+'</button>'});html+='</div>'} card.innerHTML=html; var copy=document.createElement('button');copy.className='br-copy';copy.textContent='Copy';copy.dataset.copyText=copyTextValue;copy.onclick=function(){copyText(copy.dataset.copyText||'',copy)};card.appendChild(copy); return card}
  function addThinking(){return addMsg('board','Analyzing request… checking governance, current context, and safest next action.',null,null,true,{markdown:false})}
  function founderResponse(data,fallback){if(!data)return fallback||'The request completed.';return data.board_room_response||data.executive_summary||data.message||data.next_step||fallback||'The request completed. Review the updated mission details.'}
  function setItems(id,items,empty){var el=byId(id);if(!el)return;el.innerHTML='';var values=(items&&items.length)?items:[empty];values.slice(0,5).forEach(function(s){var li=document.createElement('li');li.textContent=s;el.appendChild(li)})}
  window.toggleHistory=function(){ensureBoardWorkspace();byId('brHistory').classList.toggle('open');renderHistory();var s=byId('brHistorySearch');if(s) setTimeout(function(){s.focus()},40)}; window.loadSession=function(id){var s=sessions().find(function(x){return x.id===id}); if(!s)return; activeSession=JSON.parse(JSON.stringify(s)); var box=thread(); box.innerHTML=''; (s.messages||[]).forEach(function(m){addMsg(m.role,m.text,null,null,true,{markdown:m.role!=='user'})}); byId('brHistory').classList.remove('open'); renderHistory()}; window.pinSession=function(id){var items=sessions();items.forEach(function(s){if(s.id===id)s.pinned=!s.pinned});saveSessions(items);renderHistory()}; window.renameSession=function(id){var items=sessions();var s=items.find(function(x){return x.id===id});if(!s)return;var name=prompt('Rename conversation',s.title||'Untitled');if(!name)return;s.title=name.trim();s.updated_at=new Date().toISOString();if(activeSession&&activeSession.id===id)activeSession=s;saveSessions(items);renderHistory()}; window.renameActiveSession=function(){if(activeSession)renameSession(activeSession.id)}; window.deleteSession=function(id){if(!confirm('Delete this local conversation history?'))return;saveSessions(sessions().filter(function(s){return s.id!==id}));if(activeSession&&activeSession.id===id)newBoardChat();renderHistory()}; window.deleteActiveSession=function(){if(activeSession)deleteSession(activeSession.id)}; window.saveCurrentSession=function(){persistActiveSession();addMsg('board','Session saved to local Board Room history.',null,null)}; window.useStarter=function(text){var msg=byId('message'); if(msg){msg.value=text;msg.focus()}}; window.addInlineNote=function(text){addMsg('board',text,null,null)};
  window.renderConversationIntelligence=function(ci,meeting){if(!ci)return;ensureBoardWorkspace();var mode=byId('conversationMode');if(mode)mode.textContent=ci.mode||'General Conversation';var desc=byId('modeDescription');if(desc)desc.textContent=ci.recommended_next_action||'Review conversation.';setItems('decisionMinutes',ci.decisions,'No decisions captured yet.');setItems('actionMinutes',ci.actions,'No actions captured yet.');setItems('knowledgeMinutes',ci.knowledge,'Important context will appear here.');var meta=byId('meetingMeta');if(meta)meta.textContent=meeting||'No meeting yet.'};
  window.renderExecutiveDecision=function(decision){ensureBoardWorkspace(); var card=byId('executiveDecisionCard'); if(!card)return;if(!decision||(!decision.primary_action&&!decision.recommended_action)){card.innerHTML='<strong>Recommended Action</strong><div class="value">None yet</div><p class="muted">Send a message first.</p>';return;}var action=decision.primary_action||{}; card.innerHTML='<strong>Recommended Action</strong><div class="value">'+safe(decision.recommended_action||action.label||labelFor(action.key))+'</div><p class="muted">'+safe(decision.reason||decision.intent_type||'Recommended by Board Room action routing.')+'</p>'};
  window.renderWorkflowCard=function(wf){ensureBoardWorkspace(); var card=byId('workflowCard'); if(!card||!wf)return; var html='<strong>Current Mission</strong><div class="value">'+safe(wf.title)+'</div><p class="muted">'+safe(wf.status)+' · '+safe(wf.workflow_id)+'</p>'; if(wf.allowed_actions&&wf.allowed_actions.length){html+='<div class="br-actions">';wf.allowed_actions.forEach(function(a){html+='<button class="'+(a.indexOf('approve')>=0?'primary':'secondary')+'" onclick="workflowAction(\''+a+'\')">'+labelFor(a)+'</button>'});html+='</div>'} card.innerHTML=html; window.currentWorkflow=wf};
  window.newBoardChat=function(){ensureBoardWorkspace();renderWelcome();renderExecutiveDecision(null);setItems('decisionMinutes',null,'No decisions captured yet.');setItems('actionMinutes',null,'No actions captured yet.');setItems('knowledgeMinutes',null,'Important context will appear here.');renderHistory()}; window.openBoardRoom=function(){ensureBoardWorkspace(); if(window.showSection) window.showSection('board')}; window.startCommand=function(){ensureBoardWorkspace(); if(window.showSection) window.showSection('board'); var ci=byId('commandInput'); var msg=byId('message'); if(ci&&msg)msg.value=ci.value||''};
  window.boardRoomChat=async function(){ensureBoardWorkspace(); refreshBoardAiEngine(); var input=byId('message'); var text=(input&&input.value||'').trim(); if(!text)return; var btn=byId('boardBtn'); if(btn)btn.disabled=true; var box=thread(); if(box&&box.querySelector('.br-welcome'))box.innerHTML=''; addMsg('user',text,null,null); input.value=''; var thinking=addThinking(); if(thinking)thinking.classList.add('br-thinking'); try{var data=await post('/mission-control/operating-console/chat',Object.assign({token:token(),message:text},aiPayload())); if(thinking)thinking.remove(); if(data.board_room_response){var actionMeta=data.action_metadata||data.executive_decision;if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Meeting ID: '+data.meeting_id);renderExecutiveDecision(actionMeta);await streamMsg(data.board_room_response,actionMeta,null)}else{await streamMsg(founderResponse(data,'Board Room could not prepare a response.'),null,null)}}catch(e){if(thinking)thinking.remove();addMsg('board','Board Room request failed: '+e,null,null,false,{error:true})}finally{if(btn)btn.disabled=false; if(input)input.focus()}};
  window.createWorkflow=async function(){ensureBoardWorkspace(); addMsg('user','Accept recommended action',null,null); var thinking=addThinking(); if(thinking)thinking.classList.add('br-thinking'); var transcript=Array.from(document.querySelectorAll('#brThread .br-bubble')).map(function(n){return n.textContent}).join('\n'); try{var data=await post('/mission-control/operating-console/workflow',Object.assign({token:token(),action:'create-proposal',message:transcript},aiPayload())); if(thinking)thinking.remove(); if(data.conversation_intelligence)renderConversationIntelligence(data.conversation_intelligence,'Workflow generated');if(data.executive_decision)renderExecutiveDecision(data.executive_decision);if(data.founder_workflow){renderWorkflowCard(data.founder_workflow);await streamMsg('Workflow created. Review and approve directly from this inline card.',null,data.founder_workflow)}else{await streamMsg('Workflow request completed.',null,null)}}catch(e){if(thinking)thinking.remove();addMsg('board','Workflow request failed: '+e,null,null,false,{error:true})}};
  window.workflowAction=async function(action){if(!window.currentWorkflow){addMsg('board','No active workflow is available for this action.',null,null);return}addMsg('user',labelFor(action),null,null);try{var target=action==='approve_mission'?'repository_audit':window.currentWorkflow.current_stage;var data=await post('/mission-control/founder-workflows/advance',{token:token(),workflow_id:window.currentWorkflow.workflow_id,title:window.currentWorkflow.title,workflow_type:window.currentWorkflow.workflow_type,target_stage:target,approval_status:action.indexOf('approve')>=0?'approved':'pending'});if(data.workflow){window.currentWorkflow=data.workflow;renderWorkflowCard(data.workflow);await streamMsg('Workflow advanced. Updated status is shown below.',null,data.workflow)}else{await streamMsg(founderResponse(data,'The workflow action completed.'),null,null)}}catch(e){addMsg('board','Workflow action failed: '+e,null,null,false,{error:true})}};
  document.addEventListener('keydown',function(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();toggleHistory()}if((e.metaKey||e.ctrlKey)&&e.shiftKey&&e.key.toLowerCase()==='n'){e.preventDefault();newBoardChat()}}); document.addEventListener('DOMContentLoaded',function(){document.body.classList.add('br-hidden-modal');ensureBoardWorkspace()});
})();
</script>
"""


BR_AI_02_SCRIPT = r"""
<script>
(function(){
  var originalBoardRoomChat=null;
  var latestMemory=null;
  function byId(id){return document.getElementById(id)}
  function safe(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  async function loadMemory(){try{var r=await fetch('/platform/context?scope=mission_control'); if(!r.ok)return null; latestMemory=await r.json(); renderMemory(latestMemory); return latestMemory}catch(e){renderMemory(null,e); return null}}
  function renderMemory(memory,error){var brief=document.querySelector('.br-brief'); if(!brief)return; var card=byId('persistentMemoryCard'); if(!card){card=document.createElement('div'); card.id='persistentMemoryCard'; card.className='br-mini'; brief.insertBefore(card, byId('workflowCard'))} if(error){card.innerHTML='<strong>Persistent Memory</strong><div class="value">Unavailable</div><p class="br-memory-muted">Board Room will continue without stored context.</p>';return} var count=(memory&&memory.items&&memory.items.length)||0; var items=(memory&&memory.items||[]).slice(0,3).map(function(item){return '<li>'+safe(item.title||item.type||'Context')+'</li>'}).join(''); card.innerHTML='<strong>Persistent Memory</strong><div class="value '+(count?'br-memory-ok':'br-memory-muted')+'">'+count+' remembered context item'+(count===1?'':'s')+'</div><ul class="br-list">'+(items||'<li>No durable context captured yet.</li>')+'</ul>'}
  async function saveMemory(title,body){try{return await fetch('/platform/context/items',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'mission_control',kind:'board_room_exchange',title:title,body:body,source:'board_room'})}).then(function(r){return r.json()})}catch(e){return null}}
  function lastBoardText(){var nodes=Array.from(document.querySelectorAll('#brThread .br-msg.board .br-bubble')); var node=nodes[nodes.length-1]; return node?node.textContent:''}
  function install(){if(window.__brAi02Installed)return; if(!window.boardRoomChat){setTimeout(install,80);return} window.__brAi02Installed=true; originalBoardRoomChat=window.boardRoomChat; window.boardRoomChat=async function(){var input=byId('message'); var founderText=(input&&input.value||'').trim(); var memory=await loadMemory(); var originalFetch=window.fetch; window.fetch=function(url,opts){try{if(String(url).indexOf('/mission-control/operating-console/chat')>=0&&opts&&opts.body){var payload=JSON.parse(opts.body); if(payload&&payload.message===founderText&&memory&&memory.context_block){payload.message=founderText+'\n\nPersistent executive memory for context only; do not repeat unless relevant:\n'+memory.context_block; opts=Object.assign({},opts,{body:JSON.stringify(payload)})}}}catch(e){} return originalFetch(url,opts)}; try{await originalBoardRoomChat()}finally{window.fetch=originalFetch} var responseText=lastBoardText(); if(founderText&&responseText){await saveMemory(founderText.slice(0,120),'Founder asked: '+founderText+'\nBoard Room responded: '+responseText.slice(0,1400)); await loadMemory()}}; loadMemory()}
  document.addEventListener('DOMContentLoaded',install); setTimeout(install,120);
})();
</script>
"""


def render_board_chat_dashboard() -> str:
    html = render_stable_founder_dashboard()
    html = html.replace("</style>", BR_UI_07_STYLE + "\n</style>")
    html = html.replace("</body>", BR_UI_07_SCRIPT + BR_AI_02_SCRIPT + "\n</body>")
    return html
